window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch14"]={"id": "ch14", "title": "第十四章 新一代测序技术及其应用", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第十四章 新一代测序技术及其应用", "slides": [{"i": 0, "sec": "第一节 测序技术概述", "title": "新一代测序技术概述与第一代Sanger测序", "notes": "本章开篇指出，自Sanger测序诞生以来，测序技术经历了多次变革。新一代测序技术包括第二代和第三代测序技术：二代测序以高通量短读长为特征，三代测序注重单分子读取且读长显著提高；但目前二代测序在市场占有率和测序成本方面仍占绝对优势。本章主要介绍二代测序平台、基本原理、应用领域及生物信息学数据处理方法和流程。第一节测序技术概述回顾了测序技术发展：1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始。1977年Frederick Sanger提出双脱氧终止法（Sanger测序法），此后鸟枪法和毛细管电泳技术大幅提高测序速度和精度。Sanger测序经过30多年发展，可对长达1000bp的DNA片段测序，单碱基读取准确率高达99.999%，高通量基因组鸟枪法测序费用约0.5美元/1000个碱基。1987年ABI公司推出ABI370。该页为掌握内容，需理解第一代测序原理及其历史地位。", "page": 329, "level": "掌握", "img": "assets/img/ch14/p329.jpg", "anim": null, "fig": null, "points": ["新一代测序技术包括第二代和第三代测序技术", "第二代测序以高通量短读长为特征，第三代测序注重单分子读取且读长显著提高", "目前二代测序在市场占有率和测序成本方面仍占绝对优势", "本章主要介绍二代测序平台、基本原理、应用领域及生物信息学数据处理方法和流程", "1975年第一个测序技术诞生（Sanger测序）"], "check": {"q": "根据本章开篇的测序技术发展概述，下列关于测序技术发展历程的说法哪项正确？", "o": ["A. 1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始", "B. 第一代测序技术以高通量短读长为特征", "C. 第三代测序技术目前在市场占有率和测序成本方面仍占绝对优势", "D. 第二代测序技术注重单分子读取且读长显著提高"], "a": "A", "e": "本章开篇指出1975年第一个cDNA基因组——噬菌体φX174基因组测序完成，标志测序时代开始。二代测序以高通量短读长为特征，三代测序注重单分子读取且读长显著提高；目前二代测序在市场占有率和测序成本方面仍占绝对优势。"}, "cards": [{"front": "新一代测序技术包括哪两代？各自特点是什么？", "back": "第二代测序以高通量短读长为特征；第三代测序注重单分子读取且读长显著提高。目前二代测序在市场占有率和测序成本方面仍占绝对优势。", "mnemonic": "二代短高通量，三代长单分子", "useImg": false}]}, {"i": 1, "sec": "第一节 测序技术概述", "title": "第二代测序平台概览与第三代测序技术兴起", "notes": "本页介绍第二代测序技术的主要平台。454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）；2006年Illumina公司推出Solexa测序仪；2007年ABI推出SOLiD测序仪。这3种平台成为新一代测序主流，具备并行处理大量读长能力，具有高准确性、高通量、高灵敏度和低运行成本等优势。根据平台不同，读取长度为13～450bp；不同平台一次实验可读取高达100Gb碱基数，远超传统测序仪。表14-1列出第二代测序技术平台概览（包括部分三代测序平台），包括454、Solexa、SOLiD、Polonator、HeliScope等，涉及扩增方法、合成方法、每Mb价格、仪器价格、是否能双末端测序、错误产生类型和读长等。例如454采用乳胶PCR和并行焦磷酸合成测序法，读长约250bp，错误类型为Indel；Solexa采用桥式PCR和桥式合成测序法，读长约36bp，错误类型为Subst.；SOLiD采用乳胶PCR和基于磁珠的并行克隆连接DNA测序法，读长约35bp。第三代测序技术也悄然产生，2008年4月Helicos BioSciences公司的Timothy等在Science上报道了单分子测序技术。该页为掌握内容，需熟悉各平台特点及比较。", "page": 330, "level": "掌握", "img": "assets/img/ch14/p330.jpg", "anim": null, "fig": null, "points": ["454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）", "2006年Illumina公司推出Solexa测序仪", "2007年ABI推出SOLiD测序仪", "这3种平台成为新一代测序主流，具备并行处理大量读长能力", "具有高准确性、高通量、高灵敏度和低运行成本等优势"], "check": {"q": "关于第二代测序技术的主要平台，下列哪项说法正确？", "o": ["A. Illumina公司首先建立高通量第二代测序技术并推出454测序仪", "B. 454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪，后被Roche收购", "C. ABI公司于2006年推出Solexa测序仪", "D. Roche公司于2007年推出SOLiD测序仪"], "a": "B", "e": "454 Life Sciences公司首先建立高通量第二代测序技术并推出454测序仪（后被Roche收购）；2006年Illumina公司推出Solexa测序仪；2007年ABI推出SOLiD测序仪。"}, "cards": [{"front": "第二代测序的三大主流平台是什么？", "back": "454测序仪（Roche收购）、Solexa测序仪（Illumina）、SOLiD测序仪（ABI）。", "mnemonic": "454、Solexa、SOLiD", "useImg": false}]}, {"i": 2, "sec": "第一节 测序技术概述", "title": "Roche 454测序仪原理与流程", "notes": "本页介绍Roche 454测序仪的技术原理和流程。Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序（图14-1）。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放一分子焦磷酸，焦磷酸与腺苷-5'-磷酸硫酸（APS）结合生成ATP，荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定。图中流程包括：(a) DNA文库构建：将基因组DNA随机切割成300～800bp片段，两端加上接头，形成单链DNA文库，约4.5小时；(b) 乳液PCR扩增：单链DNA文库固定在DNA捕获磁珠上，磁珠表面有与文库DNA片段末端互补的寡核苷酸片段，可特异配对连接。乳液PCR利用油水混合物形成油包水稳定乳浊液，将珠子分开，保证每个珠子仅与特定片段连接，珠子内含有PCR反应物。经过约8小时扩增，每个珠子表面可有超过1,000,000个拷贝用于后续测序；(c) 测序：将携带DNA扩增片段的珠子放入PTP（picotiter plate，fused silica capillary structure）板，每个孔只允许结合一个磁珠。将PTP板置于GS FLX中开始测序，每当有核苷酸加到DNA片段上，荧光素酶催化相关反应释放相应强度荧光信号，通过信号转换准确快速获得模板碱基序列，约7.5小时。该页为掌握内容，需理解焦磷酸测序原理及乳液PCR步骤。", "page": 331, "level": "掌握", "img": "assets/img/ch14/p331.jpg", "anim": null, "fig": "图14-1展示Roche 454测序原理与流程。看图时注意从(a)到后续步骤的顺序，理解焦磷酸释放、ATP生成和荧光信号产生的连锁反应。", "points": ["Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序", "在DNA聚合酶催化下，dNTP加入DNA的3'端并释放一分子焦磷酸", "焦磷酸与腺苷-5'-磷酸硫酸（APS）结合生成ATP", "荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定", "图中流程包括：(a) DNA文库制备等步骤"], "check": {"q": "Roche 454测序仪的主要技术原理是什么？", "o": ["A. 大规模并行连接测序", "B. 大规模并行焦磷酸合成测序", "C. 桥式PCR合成测序", "D. 单分子荧光合成测序"], "a": "B", "e": "Roche/454 FLX Pyrosequencer主要技术原理是大规模并行焦磷酸合成测序。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放焦磷酸，焦磷酸与APS结合生成ATP，荧光素酶催化氧化荧光素裂解并发出荧光，从而进行测定。"}, "cards": [{"front": "Roche 454测序仪的主要技术原理是什么？", "back": "大规模并行焦磷酸合成测序。在DNA聚合酶催化下，dNTP加入DNA的3'端并释放焦磷酸，焦磷酸与APS结合生成ATP，荧光素酶催化氧化荧光素裂解，同时发出荧光，从而进行测定。", "mnemonic": "焦磷酸→ATP→荧光", "useImg": false}]}, {"i": 3, "sec": "第一节 测序技术概述", "title": "454测序文库制备、乳液PCR与测序步骤", "notes": "本页详细说明454测序的三个主要步骤。1) 文库制备：随机切割样品基因组获得大量DNA片段。GS FLX系统支持各种来源样品，包括基因组DNA、PCR产物、BAC、cDNA、小分子RNA等。大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断。然后在3'端和5'端接上接头进行扩增反应，具有接头的单链DNA片段组成样品文库（图14-1a）。2) 乳液PCR扩增：单链DNA文库固定在特别设计的DNA捕获磁珠上。磁珠表面有很多可与文库中DNA片段末端互补的寡核苷酸片段，因此可与特异DNA片段配对连接。乳液PCR利用油水混合物形成油包水稳定乳浊液，将珠子分开，保证每个珠子仅与特定片段连接，珠子内同样含有PCR所需反应物。经过一小时扩增后，每个珠子表面可有多余1,000,000个拷贝用于后续测序（图14-1b）。3) 测序：将携带DNA扩增片段的珠子放入PTP（picotiter plate）板上，由于PTP孔直径较小，每个孔只允许结合一个磁珠。将PTP板置于GS FLX中开始测序。每当有核苷酸加到DNA片段上，荧光素酶催化相关反应释放相应强度荧光信号，通过信号转换后准确快速获得模板碱基序列（图14-1c）。尽管GS FLX测序系统准确率较高，一般在99%以上，但该方法也有不足之处：如果被测序片段中含有几个连续相同碱基，测序时会连续发出同样光信号，由于没有终止元件来终止反应，信号会不断发出，导致同聚物错误。该页为掌握内容，需理解各步骤细节及局限性。", "page": 332, "level": "掌握", "img": "assets/img/ch14/p332.jpg", "anim": null, "fig": null, "points": ["454测序的三个主要步骤：文库制备、乳液PCR、测序", "文库制备：随机切割样品基因组获得大量DNA片段", "GS FLX系统支持各种来源样品，包括基因组DNA、PCR产物、BAC、cDNA、小分子RNA等", "大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断", "在3'端和5'端接上接头进行扩增反应"], "check": {"q": "关于454测序的文库制备，下列哪项说法正确？", "o": ["A. 所有样品都必须打断成300～800bp片段", "B. 小分子非编码RNA或PCR扩增产物也需要打断", "C. 大样品如基因组DNA或BAC被打断成300～800bp片段，小分子非编码RNA或PCR扩增产物则不需要打断", "D. 文库制备后直接进行测序，无需乳液PCR扩增"], "a": "C", "e": "454测序文库制备中，大样品如基因组DNA或BAC被打断成300～800bp片段；小分子非编码RNA或PCR扩增产物则不需要打断。然后在3'端和5'端接上接头进行扩增反应，具有接头的单链DNA片段组成样品文库。"}, "cards": [{"front": "454测序的三个主要步骤是什么？", "back": "1) 文库制备：随机切割样品基因组获得大量DNA片段，接上接头；2) 乳液PCR；3) 测序。", "mnemonic": "文库、乳液PCR、测序", "useImg": false}]}, {"i": 4, "sec": "第一节 测序技术概述", "title": "Illumina/Solexa测序原理与流程", "notes": "本页介绍Illumina/Solexa测序原理（图14-2）。流程包括：(a) 文库制备与桥式PCR：将样本基因组DNA随机打断并接上接头，单链DNA片段与玻璃板上的引物杂交结合；双链解链后，另一端与平板上引物结合形成桥式连接，并进行扩增。经过多轮扩增，在测序flow cell中形成密集的簇。(b) 测序：在测序flow cell中加入4种荧光标记的dNTP、DNA聚合酶及接头引物，每加入一个标记的dNTP就能释放出相应的荧光，测序仪捕获荧光信号，并通过计算机软件将光信号转化为测序峰，从而获得待测片段的序列信息。从荧光信号获取待测片段序列信息的过程叫做Base Calling。经过足够的反应循环后，得到database profile。Illumina公司Base Calling所用的软件是Illumina's Genome Analyzer Sequencing Control Software and Pipeline Analysis Software。该页为掌握内容，需理解桥式PCR和可逆终止子测序原理。", "page": 333, "level": "掌握", "img": "assets/img/ch14/p333.jpg", "anim": null, "fig": "图14-2展示Illumina/Solexa测序原理。看图时注意桥式PCR的形成过程和测序时荧光标记dNTP的加入与读取。", "points": ["Illumina/Solexa测序流程包括：(a) 文库制备与桥式PCR；(b) 测序", "文库制备与桥式PCR：将样本基因组DNA随机打断并接上接头，单链DNA片段与玻璃板上的引物杂交结合", "双链解链后，另一端与平板上引物结合形成桥式连接，并进行扩增", "经过多轮扩增，在测序flow cell中形成密集的簇", "测序：在测序flow cell中加入4种荧光标记的dNTP"], "check": {"q": "Illumina/Solexa测序流程中，在测序flow cell中形成密集的簇是通过什么方式实现的？", "o": ["A. 乳液PCR", "B. 桥式PCR", "C. 连接酶反应", "D. 焦磷酸测序"], "a": "B", "e": "Illumina/Solexa测序流程中，单链DNA片段与玻璃板上的引物杂交结合，双链解链后另一端与平板上引物结合形成桥式连接并进行扩增，经过多轮扩增，在测序flow cell中形成密集的簇。"}, "cards": [{"front": "Illumina/Solexa测序流程包括哪两个主要步骤？", "back": "(a) 文库制备与桥式PCR：DNA片段与玻璃板上的引物杂交结合，形成桥式连接并扩增，形成密集的簇；(b) 测序：加入4种荧光标记的dNTP进行测序。", "mnemonic": "桥式PCR，荧光测序", "useImg": false}]}, {"i": 5, "sec": "第一节 测序技术概述", "title": "SOLiD测序原理与流程", "notes": "本页介绍SOLiD测序仪的原理和流程。1) 文库制备：SOLiD测序仪支持两种测序文库：片段文库（fragment library）或配对末端文库（mate-paired library）。片段文库就是将基因组DNA打断，两头加上接头，制成文库。配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切，使中间接头两端各有25～27bp的碱基，再加上两端的接头，形成文库。2) 微乳液PCR扩增：在微反应器中加入测序模板、PCR反应元件、微珠和引物，进行乳液PCR（emulsion PCR）。PCR扩增反应结束后，变性模板，富集带有延伸模板的微珠，去除多余的微珠。微珠上的模板经过3'修饰，可以与玻片共价结合，从而制成高密度测序芯片。3) SOLiD测序反应：采用双碱基探针，探针上有第1位和第2位碱基标记荧光，通过连接反应确定序列。图中显示SOLiD反应底物、模板、玻璃平板、剪切位点、启动并连接、重复1～4延长合成链、链接循环、Universal seq primer等步骤。SOLiD测序通过多次连接循环和引物重置，最终获得序列信息。该页为掌握内容，需理解SOLiD连接测序原理及双碱基编码特点。", "page": 334, "level": "掌握", "img": "assets/img/ch14/p334.jpg", "anim": null, "fig": null, "points": ["SOLiD测序仪支持两种测序文库：片段文库或配对末端文库", "片段文库就是将基因组DNA打断，两头加上接头，制成文库", "配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切", "使中间接头两端各有25～27bp的片段"], "check": {"q": "关于SOLiD测序仪的文库制备，下列哪项说法正确？", "o": ["A. SOLiD只支持片段文库", "B. SOLiD只支持配对末端文库", "C. SOLiD支持片段文库或配对末端文库两种", "D. SOLiD不支持任何文库构建"], "a": "C", "e": "SOLiD测序仪支持两种测序文库：片段文库（fragment library）或配对末端文库（mate-paired library）。片段文库是将基因组DNA打断，两头加上接头制成文库；配对末端文库是将基因组DNA打断后与中间接头连接，再环化，然后用EcoP15酶切，使中间接头两端各有25～27bp碱基，再加上两端接头形成文库。"}, "cards": [{"front": "SOLiD测序仪支持哪两种测序文库？", "back": "片段文库和配对末端文库。片段文库是将基因组DNA打断，两头加上接头；配对末端文库是将基因组DNA打断后，与中间接头连接，再环化，然后用EcoP15酶切。", "mnemonic": "片段文库、配对末端文库", "useImg": false}]}, {"i": 6, "sec": "第二节 第二代测序原理", "title": "SOLiD连接测序原理", "notes": "本页介绍SOLiD测序仪的连接测序原理。SOLiD不使用聚合酶，而采用连接酶。通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端。探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。每次连接反应加入一种8碱基荧光探针，记录第1、2位编码区颜色信息，随后化学处理断裂探针第5、6位碱基间的化学键，进行下一轮连接。图14-3展示了双碱基编码矩阵：16种双碱基组合对应4种颜色，通过多轮连接和颜色解码，最终还原DNA序列。该技术通过双碱基编码，每个碱基被读取两次，提高准确度。", "page": 335, "level": "掌握", "img": "assets/img/ch14/p335.jpg", "anim": null, "fig": null, "points": ["SOLiD不使用聚合酶，而采用连接酶", "通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端", "探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色", "第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基", "每次连接反应加入一种8碱基荧光探针，记录第1、2位碱基信息"], "check": {"q": "SOLiD连接测序原理中，连接酶连接的荧光标记核酸探针长度是多少？", "o": ["A. 4bp", "B. 6bp", "C. 8bp", "D. 10bp"], "a": "C", "e": "SOLiD不使用聚合酶而采用连接酶。通用引物与模板片段两端的接头序列互补结合，连接酶将一个荧光标记的8bp核酸探针连接到引物末端。探针5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区决定探针颜色。"}, "cards": [{"front": "SOLiD连接测序原理中，探针的结构是怎样的？", "back": "探针为8bp核酸探针，5端标记4种颜色的荧光染料，3端第1、2位碱基构成编码区，决定探针颜色；第3-5位为随机碱基，第6-8位为可与任何碱基配对的特殊碱基。", "mnemonic": "8bp探针，1-2位编码，3-5随机，6-8特殊", "useImg": false}]}, {"i": 7, "sec": "第二节 第二代测序原理", "title": "SOLiD数据分析及第二代测序技术应用概述", "notes": "本页首先介绍SOLiD数据分析：测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵，只要知道DNA序列中任一位置的碱基类型，即可将颜色序列解码为碱基序列。双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。随后进入第三节“第二代测序技术的应用”，概述第二代测序不仅用于测序，还能研究已知和未知物种基因组，快速获得基因组数据，鉴定转录基因、同源基因、新基因、表达水平、体细胞突变和可变剪切，深入重测序可了解疾病相关遗传作用。通过捕获序列片段，可应用于外显子测序等，推动各种组学诞生。最后介绍全基因组测序与重测序（DNA-seq）：可得到已知或未知基因组样本的DNA片段序列，通过组装获得全基因组图谱；重测序是对已知基因组序列的物种进行不同个体测序，分析个体或群体差异。高通量测序可跨过构建文库步骤，避免亚克隆偏差，依靠生物信息学分析。", "page": 336, "level": "掌握", "img": "assets/img/ch14/p336.jpg", "anim": null, "fig": null, "points": ["SOLiD数据分析：测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵解码为碱基序列", "双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高", "第二代测序不仅用于测序，还能研究已知和未知物种基因组", "快速获得基因组信息"], "check": {"q": "关于SOLiD数据分析及第二代测序技术应用，下列哪项说法正确？", "o": ["A. SOLiD测序后获得4种颜色编码的原始序列，双碱基编码使每个碱基判读两遍，原始碱基准确度大于99.94%", "B. SOLiD测序后直接获得碱基序列，无需解码", "C. 双碱基编码使每个碱基只判读一遍", "D. 第二代测序只能用于测序，不能研究基因表达"], "a": "A", "e": "SOLiD测序后获得4种颜色编码的原始序列，根据双碱基编码矩阵，只要知道DNA序列中任一位置的碱基类型，即可将颜色序列解码为碱基序列。双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。"}, "cards": [{"front": "SOLiD测序的双碱基编码有什么优势？", "back": "双碱基编码使每个碱基判读两遍，减少错误，原始碱基准确度大于99.94%，为新一代测序中最高。", "mnemonic": "双碱基编码，准确度最高", "useImg": false}]}, {"i": 8, "sec": "第二节 第二代测序原理", "title": "小RNA测序、lncRNA测序及ChIP-seq", "notes": "本页继续介绍第二代测序的应用。首先是小RNA测序：对small RNA进行大规模测序分析，可获得全基因组水平的microRNA图谱，实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等。长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质，但能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达。多数lncRNA无polyA尾，而常用RNA-seq利用polyA尾捕获转录本，因此主要获得编码蛋白质的转录本，lncRNA很少。目前针对ncRNA测序最好的策略是rRNA消解法构建文库，但该方法不成熟、费用高，专门针对lncRNA的测序很少。接着介绍表观组学测序和染色质免疫共沉淀测序（ChIP-seq）：ChIP是研究体内蛋白质与DNA相互作用的有力工具，用于定位全基因组范围内的结合位点或表观遗传学修饰。图中展示了ChIP-seq流程：DNA片段化、免疫共沉淀、纯化、接头连接、PCR扩增、Illumina Genome Analyzer测序、图像识别和序列信息分析。", "page": 337, "level": "理解", "img": "assets/img/ch14/p337.jpg", "anim": null, "fig": null, "points": ["小RNA测序：对small RNA进行大规模测序分析，可获得全基因组水平的microRNA图谱", "实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等", "长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质", "lncRNA能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达"], "check": {"q": "关于小RNA测序和lncRNA测序，下列哪项说法正确？", "o": ["A. 小RNA测序不能获得全基因组水平的microRNA图谱", "B. lncRNA是一类长度超过200nt的非编码RNA，不编码蛋白质", "C. 多数lncRNA有polyA尾，常用RNA-seq利用polyA尾捕获转录本", "D. lncRNA不能调控基因表达"], "a": "B", "e": "长链非编码RNA（lncRNA）是一类长度超过200nt的非编码RNA，不编码蛋白质，但能以RNA形式在转录水平、转录后水平及表观修饰水平调控基因表达。多数lncRNA无polyA尾，而常用RNA-seq利用polyA尾捕获转录本。小RNA测序可获得全基因组水平的microRNA图谱。"}, "cards": [{"front": "小RNA测序可以获得哪些信息？", "back": "可获得全基因组水平的microRNA图谱，实现新microRNA鉴定、差异表达分析、microRNA聚类和表达谱分析等。", "mnemonic": "microRNA图谱、鉴定、表达分析", "useImg": false}]}, {"i": 9, "sec": "第二节 第二代测序原理", "title": "DNA甲基化测序方法", "notes": "本页介绍DNA甲基化测序。重硫酸盐测序法是一种化学转变法，原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。随着测序发展，发现不仅5mC抵抗重硫酸盐转化，5-羟甲基胞嘧啶（5hmC，5mC和胞嘧啶的中间态）也抵抗转化。随后提出hMeDIP-seq，利用抗体免疫共沉淀捕获5hmC序列，但分辨率和质量不佳。2013年提出氧化重硫酸测序（oxBS-seq）和TET相关的重硫酸测序（TAB-seq）。例如oxBS-seq中，5hmC先被化学氧化成5fC，再经重硫酸盐处理转化为尿嘧啶。利用oxBS-seq得到的DNA甲基化片段比MethylC-seq少，少的部分即5hmC。图14-5展示了Illumina Genome Analyzer MeDIP-seq测序过程：DNA片段化、接头连接、免疫沉淀、测序、图像识别和甲基化序列信息分析。", "page": 338, "level": "理解", "img": "assets/img/ch14/p338.jpg", "anim": null, "fig": null, "points": ["重硫酸盐测序法是一种化学转变法，原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变", "主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）", "5-羟甲基胞嘧啶（5hmC，5mC和胞嘧啶的中间态）也抵抗重硫酸盐转化"], "check": {"q": "关于DNA甲基化测序方法，下列哪项说法正确？", "o": ["A. 重硫酸盐处理后的基因组中甲基化的胞嘧啶转换为尿嘧啶", "B. 重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变", "C. 5-羟甲基胞嘧啶（5hmC）不能抵抗重硫酸盐转化", "D. hMeDIP-seq分辨率和质量均优于其他方法"], "a": "B", "e": "重硫酸盐测序法原理是重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。5hmC也抵抗重硫酸盐转化。hMeDIP-seq利用抗体免疫共沉淀捕获5hmC序列，但分辨率和质量不佳。"}, "cards": [{"front": "重硫酸盐测序法的原理是什么？", "back": "重硫酸盐处理后的基因组中未甲基化的胞嘧啶转换为尿嘧啶，而甲基化的胞嘧啶不变。主要方法有全基因组重硫酸盐测序（MethylC-seq或BS-seq）和简化表达重硫酸盐测序（RRBS）。", "mnemonic": "未甲基化C→U，甲基化C不变", "useImg": false}]}, {"i": 10, "sec": "第二节 第二代测序原理", "title": "多因素数据统计分析、RASH及NGS数据获取", "notes": "本页首先介绍多因素数据统计分析（two-way ANOVA）：根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因。接着介绍RASH：用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中，聚在同一簇的基因可能具有类似生物学功能。常用聚类方法有层次聚类、K-means聚类和DBSCAN算法。然后介绍机器学习及其他分析方法：由于生物数据复杂性，可根据样本数据和目的采用主成分分析、遗传算法、人工神经网络、支持向量机、自组织映射、置信网络、隐马尔可夫模型等，数据挖掘中可能用到多种方法。综上，第二代测序数据处理需要高性能计算机和精通多种程序语言的生物信息学家，其发展也推动了生物信息学发展。最后进入第四节“生物信息学在第二代测序中的应用”，介绍NGS数据获取：可根据研究需要自行设计文库测序，2007年NCBI建立了新一代测序结果子数据库，数据可提交至NCBI SRA、EBI ENA和DDBJ DTA。其他获取途径见表14-2，主要生物信息学工具见表14-3。", "page": 339, "level": "了解", "img": "assets/img/ch14/p339.jpg", "anim": null, "fig": null, "points": ["多因素数据统计分析（two-way ANOVA）：根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因", "RASH：用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中", "聚在同一簇的基因可能具有类似生物学功能", "常用聚类方法有层次聚类、K-means聚类和DBSCAN算法", "机器学习及其他分析方法"], "check": {"q": "关于多因素数据统计分析和RASH，下列哪项说法正确？", "o": ["A. two-way ANOVA只能分析一个条件对两组样品造成的差异基因", "B. RASH是用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中", "C. 常用聚类方法只有层次聚类一种", "D. 机器学习方法不能用于生物数据分析"], "a": "B", "e": "多因素数据统计分析（two-way ANOVA）根据一个以上不同条件综合评判，筛选多个条件对两组样品造成的差异基因。RASH用挑选的差异基因的表达情况计算样品间的相关性，同一类样品能通过聚类出现在同一个簇中，聚在同一簇的基因可能具有类似生物学功能。常用聚类方法有层次聚类、K-means聚类和DBSCAN算法。"}, "cards": [{"front": "RASH分析中常用的聚类方法有哪些？", "back": "层次聚类、K-means聚类和DBSCAN算法。", "mnemonic": "层次、K-means、DBSCAN", "useImg": false}]}, {"i": 11, "sec": "第二节 第二代测序原理", "title": "NGS数据分析的主要生物信息学工具", "notes": "本页为表14-3，列出NGS数据分析的主要生物信息学工具，包括工具名称、说明和网址。工具涵盖序列匹配、组装和可视化：Velvet用于短片段序列的重新组装拼接；EULER用于Sanger测序和NGS混合片段组装；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组，能进行单一或末端匹配的重测序、smRNA发现及mRNA标签序列匹配；TOPS用于序列匹配；VCAKE用于短片段组装；JMP Genomics用于NGS数据可视化及统计分析；还有挖掘序列变异的工具。表中还包含二维码和网址。读表时注意工具功能分类：组装、匹配、可视化、变异挖掘等，可根据研究需求选择合适工具。", "page": 340, "level": "了解", "img": "assets/img/ch14/p340.jpg", "anim": null, "fig": "表14-3列出NGS数据分析的主要生物信息学工具。查看时注意工具名称、功能说明和网址，根据分析需求选择合适工具。", "points": ["表14-3列出NGS数据分析的主要生物信息学工具，包括工具名称、说明和网址", "工具涵盖序列匹配、组装和可视化", "Velvet用于短片段序列的重新组装拼接", "EULER用于Sanger测序和NGS混合片段组装", "MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组"], "check": {"q": "在表14-3列出的NGS数据分析工具中，哪个工具用于短片段序列的重新组装拼接？", "o": ["A. MOSAIK", "B. RMAP", "C. Velvet", "D. SOAP"], "a": "C", "e": "表14-3中，Velvet用于短片段序列的重新组装拼接；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SOAP将有缺口或无缺口片段匹配到参考基因组。"}, "cards": [{"front": "表14-3中列出的NGS数据分析工具主要涵盖哪些功能？", "back": "序列匹配、组装和可视化。例如Velvet用于短片段序列的重新组装拼接；EULER用于Sanger测序和NGS混合片段组装；MOSAIK用于NGS序列匹配；RMAP将短片段匹配到参考基因组；SHARCGS用于短片段重组装；SOAP将有缺口或无缺口片段匹配到参考基因组。", "mnemonic": "匹配、组装、可视化", "useImg": false}]}, {"i": 12, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "RNA-seq生物信息学分析流程（无参考基因组与有参考基因组）", "notes": "本页介绍RNA-seq中的生物信息学分析，重点区分无参考基因组和有参考基因组两种策略。无参考基因组转录组分析（图14-6）流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等RNA-seq分析软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达差异分析及差异表达Unigene的GO功能注释。图14-6展示mRNA经片段化、逆转录、测序得到短读长，包括外显子读长、连接区读长和PolyA读长，再经从头组装定位到转录本。有参考基因组转录组分析（图14-7）流程包括：测序数据产量统计、去除冗余数据、与参考基因组比对后的注释信息；采用Cufflinks等重建转录本；Reads在基因组上的分布；测序深度分布、测序随机性评估；基因差异表达分析；新基因预测、可变剪接鉴定、基因融合鉴定、已知和新的非编码RNA鉴定。small RNA和miRNA测序分析包括small RNA分类注释，与Rfam数据库及GeneBank比对等。", "page": 341, "level": "掌握", "img": "assets/img/ch14/p341.jpg", "anim": null, "fig": "图14-6展示无参考基因组转录组分析流程。看图时注意从测序数据到功能注释的各个步骤，理解无参考基因组情况下的组装和注释策略。", "points": ["RNA-seq中的生物信息学分析，重点区分无参考基因组和有参考基因组两种策略", "无参考基因组转录组分析流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估", "采用Cufflinks等RNA-seq分析软件重建转录本", "计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类", "代谢通路分析；Unigene表达分析"], "check": {"q": "关于无参考基因组转录组分析流程，下列哪项说法正确？", "o": ["A. 无参考基因组分析不需要进行测序数据产量统计", "B. 无参考基因组分析流程包括测序数据产量统计、去除冗余数据、数据成分与质量评估，采用Cufflinks等软件重建转录本", "C. 无参考基因组分析不能进行GO分类", "D. 无参考基因组分析不需要进行代谢通路分析"], "a": "B", "e": "无参考基因组转录组分析流程包括：测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等RNA-seq分析软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达差异分析及差异表达Unigene的GO功能注释。"}, "cards": [{"front": "无参考基因组转录组分析流程包括哪些主要步骤？", "back": "测序数据产量统计、去除冗余数据、数据成分与质量评估；采用Cufflinks等软件重建转录本；计算Contig和Scaffold长度分布；Unigene长度分布、功能注释、GO分类；代谢通路分析；Unigene表达分析。", "mnemonic": "统计→去冗余→评估→重建→注释→通路→表达", "useImg": false}]}, {"i": 13, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "有参考基因组RNA-seq分析策略与ChIP-seq分析", "notes": "本页继续讲解有参考基因组的RNA-seq分析策略（图14-7），左图为“先匹配再组装”，右图为“先组装再匹配”。先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配是先将读长组装成转录本，再比对到基因组。随后介绍ChIP-seq相关分析：统计样品Unique mapped reads在重复区域、基因区间、基因上的分布情况和覆盖深度；统计分析每个样品中与基因相关的Peak信息并找到这些基因；对Peak相关基因进行GO功能显著性富集分析；不同样本中基因的ChIP-seq信息差异分析；转录因子结合区域分析和motif挖掘（图14-8）；甲基化和组蛋白修饰检测比较；不同表观遗传修饰对基因表达调控的影响（图14-9）。图14-8展示motif分析流程：被测序的短读长比对到参考基因组，经计算后合并为新的motif。", "page": 342, "level": "掌握", "img": "assets/img/ch14/p342.jpg", "anim": null, "fig": "图14-7展示有参考基因组RNA-seq分析的两种策略。看图时注意左右两图的区别：左图先比对再组装，右图先组装再比对。", "points": ["有参考基因组的RNA-seq分析策略（图14-7），左图为“先匹配再组装”，右图为“先组装再匹配”", "先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本", "先组装再匹配是先将读长组装成转录本，再比对到基因组", "ChIP-seq相关分析：统计样品Unique mapped reads在重复区域、基因区间、基因上的分布情况和覆盖深度"], "check": {"q": "关于有参考基因组RNA-seq分析策略，下列哪项说法正确？", "o": ["A. 只有“先匹配再组装”一种策略", "B. 只有“先组装再匹配”一种策略", "C. 包括“先匹配再组装”和“先组装再匹配”两种策略", "D. 有参考基因组分析不需要比对到参考基因组"], "a": "C", "e": "有参考基因组的RNA-seq分析策略包括两种：先匹配再组装是将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配是先将读长组装成转录本，再比对到基因组。"}, "cards": [{"front": "有参考基因组RNA-seq分析的两种策略是什么？", "back": "先匹配再组装：将读长先比对到参考基因组，再合并分散片段为转录本；先组装再匹配：先将读长组装成转录本，再比对到基因组。", "mnemonic": "先匹配再组装 vs 先组装再匹配", "useImg": false}]}, {"i": 14, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "表观遗传修饰测序分析与NGS功能基因组学应用", "notes": "本页展示利用第二代测序分析表观遗传修饰（图14-9），包括BS-seq流程和ChIP-seq流程。BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化。ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增后测序，将读长比对到基因组，用于检测转录因子结合位点和组蛋白修饰。图14-9还展示UCSC Genome Browser和Anno-J Browser等可视化工具，以及染色体位置上的信号峰。随后介绍NGS在功能基因组学中的应用：NGS可得到基因水平、转录水平和蛋白质水平的不同数据，利用生物信息学手段综合不同水平进行研究，结果更具生物学意义。图14-10是基于NGS在功能基因组学中综合研究的例子。最后引出第五节生物信息学新技术与发展趋势，指出二代、三代测序技术推动研究模式革新，生物信息学研究正向精准化发展。", "page": 343, "level": "理解", "img": "assets/img/ch14/p343.jpg", "anim": null, "fig": "图14-9展示表观遗传修饰测序分析流程。看图时注意BS-seq和ChIP-seq两个流程的步骤差异，理解各自用于检测DNA甲基化和蛋白质-DNA结合。", "points": ["利用第二代测序分析表观遗传修饰（图14-9），包括BS-seq流程和ChIP-seq流程", "BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变", "经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化", "ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增"], "check": {"q": "关于利用第二代测序分析表观遗传修饰，下列哪项说法正确？", "o": ["A. BS-seq流程中，DNA经亚硫酸氢盐处理后所有胞嘧啶都转化为尿嘧啶", "B. ChIP-seq流程用于检测DNA甲基化", "C. BS-seq流程中未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，用于检测DNA甲基化", "D. ChIP-seq不需要抗体免疫沉淀"], "a": "C", "e": "BS-seq流程：DNA经亚硫酸氢盐处理，未甲基化的胞嘧啶C转化为尿嘧啶U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组，用于检测DNA甲基化。ChIP-seq流程：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增后测序，将读长比对到基因组，用于检测转录因子结合位点和组蛋白修饰。"}, "cards": [{"front": "BS-seq和ChIP-seq流程分别用于检测什么？", "back": "BS-seq用于检测DNA甲基化：DNA经亚硫酸氢盐处理，未甲基化的C转化为U，甲基化的C保持不变，经PCR扩增后测序，再将读长比对到基因组。ChIP-seq用于检测蛋白质-DNA结合：蛋白质与DNA结合，经超声波处理、抗体免疫沉淀、提纯DNA、连接接头、PCR扩增。", "mnemonic": "BS-seq测甲基化，ChIP-seq测蛋白结合", "useImg": false}]}, {"i": 15, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "NGS功能基因组学综合应用与单细胞测序", "notes": "本页展示图14-10 NGS在功能基因组学中的综合应用（Werner, 2010）。该图显示DNA-Seq和RNA-Seq的初步分析：DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等；RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等。这些数据进一步用于数据库、通路、调控网络和网络重建，通过多重相关性、多重实验整合分析。随后介绍单细胞测序（single-cell sequencing, SCS）技术（图14-11），可在单细胞水平上检测基因组和转录组。George Daley等使用单细胞测序揭示了干细胞多能性的更多变化。单细胞组学在癌症和免疫治疗中具有重要意义：癌症细胞具有异质性，除患者间异质性外，同一肿瘤中也存在不同亚群，不同肿瘤细胞抗原表面排布也有异质性。", "page": 344, "level": "理解", "img": "assets/img/ch14/p344.jpg", "anim": null, "fig": "图14-10展示NGS在功能基因组学中的综合应用。看图时注意DNA-Seq和RNA-Seq的分析产出如何整合到数据库、通路和调控网络中。", "points": ["图14-10展示NGS在功能基因组学中的综合应用（Werner, 2010）", "DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等", "RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等", "这些数据进一步用于数据库、通路、调控网络和网络重建", "通过多重相关性、多重分析等整合"], "check": {"q": "关于单细胞测序，下列哪项说法正确？", "o": ["A. 单细胞测序不能用于研究癌症内异质性", "B. 单细胞测序可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究", "C. 单细胞测序只能研究基因表达水平，不能发现非编码RNA", "D. 单细胞测序已完全取代其他测序技术"], "a": "B", "e": "单细胞测序可帮助研究癌症内异质性，也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究。单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升，已成为研究热点。"}, "cards": [{"front": "图14-10中NGS在功能基因组学中的综合应用包括哪些初步分析？", "back": "DNA-Seq包括reads、de novo组装、CNV、SNP、InDel等；RNA-Seq包括reads、新转录本/基因座、可变剪接位点、基因融合等。这些数据进一步用于数据库、通路、调控网络和网络重建。", "mnemonic": "DNA-Seq和RNA-Seq分析整合到网络", "useImg": false}]}, {"i": 16, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "单细胞测序应用与宏基因组学", "notes": "本页继续介绍单细胞测序的应用：在嵌合抗原受体T细胞（CAR-T）疗法中，经过CAR改造的T细胞识别和杀伤肿瘤抗原时产生的免疫反应有所不同。单细胞测序可帮助研究癌症内异质性，也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究。单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升，已成为研究热点，其临床应用被国家立为重点专项。细胞是执行生命活动的最小单位，单细胞组学的发展预示人类对生物机制的研究达到新高度。2016年启动的人类细胞图谱计划将对所有不同的人类细胞进行高度分类，收集细胞生理学、组织学、功能信息等多方面数据。图14-11展示单细胞测序流程（Nawy, 2014）：单细胞分离、逆转录、扩增cDNA、准备测序文库、测序。随后介绍宏基因组学（metagenomics）：以某一环境中全体微生物基因组为研究对象，利用生物信息学方法分析微生物群落的多样性、种群结构、功能活性和相互作用等关系。宏基因组最初应用于海洋、土壤等研究领域，现在也广泛应用于医学研究，如人类与共生体肠道菌群、感染性疾病等相互关系的研究。最初对环境中微生物群落的研究是根据保守的16S rRNA基因。", "page": 345, "level": "掌握", "img": "assets/img/ch14/p345.jpg", "anim": null, "fig": null, "points": ["单细胞测序在嵌合抗原受体T细胞（CAR-T）疗法中，经过CAR改造的T细胞识别和杀伤肿瘤抗原时产生的免疫反应有所不同", "单细胞测序可帮助研究癌症内异质性", "也可对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究", "单细胞测序使基因表达水平的测量精度及对罕见非编码RNA的发现能力都得到提升", "已成为研究热点，其临床应用被国家立为重点专项"], "check": {"q": "关于人类微生物组计划（HMP），下列哪项说法正确？", "o": ["A. HMP只研究人类胃肠道微生物", "B. HMP主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程", "C. 2017年9月HMP进入第一阶段", "D. HMP不涉及微生物菌群结构与健康关系的研究"], "a": "B", "e": "人类微生物组计划（HMP）主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果。HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系。"}, "cards": [{"front": "单细胞测序有哪些应用？", "back": "在CAR-T疗法中研究免疫反应差异；研究癌症内异质性；对肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞进行研究；提升基因表达水平测量精度及罕见非编码RNA发现能力。", "mnemonic": "CAR-T、癌症异质性、CTC、早期胚胎", "useImg": false}]}, {"i": 17, "sec": "第四节 生物信息学在第二代测序中的应用", "title": "人类微生物组计划、细胞微环境与三维基因组学", "notes": "本页介绍人类微生物组计划（HMP，http://www.hmpdacc.org/），主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果。HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系。2016年美国国家微生物组计划将视野拓展到人类之外的生态系统。细胞的活动不仅取决于自身基因组特征，也受周围同类细胞、基质细胞、细胞间质、细胞外基质等因素影响，这些因素统称为细胞微环境（microenvironment）。近年来以癌症细胞为典型的基因组学研究已开始考虑细胞微环境的影响。随后介绍三维基因组学：人类基因组计划完成代表了解序列的第一阶段；ENCODE计划完成标志着对各种基因组元件的了解；然而细胞内部染色体复杂的三维结构使得各功能元件、游离RNA分子和蛋白质复合物之间的相互作用异常复杂。以Hi-C技术为代表的空间构象捕获技术的发展，推动了基因组学的第三次浪潮，即三维基因组学。早期基因组学研究往往从线性角度分析基因组，一维距离上相距很远的两个基因可能会有很频繁的互作，这是因为DNA与蛋白质高度浓缩折叠成染色质，这种折叠结构在调控过程中扮演重要角色。", "page": 346, "level": "理解", "img": "assets/img/ch14/p346.jpg", "anim": null, "fig": null, "points": ["人类微生物组计划（HMP，http://www.hmpdacc.org/），主要包括人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程", "2017年9月，HMP进入第二阶段，公开了对1631个新样本的宏基因组测序结果", "HMP致力于研究与人体共生的微生物的菌群结构、分子过程与健康的关系", "2016年美国国家微生物组计划将视野拓展到人类之外"], "check": {"q": "关于4D核体计划与Hi-C技术，下列哪项说法正确？", "o": ["A. 4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范", "B. Hi-C技术流程中不需要甲醛交联", "C. Hi-C技术流程中不需要生物素标记", "D. 4D核体计划只包括图谱绘制一个部分"], "a": "A", "e": "4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范，建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响。Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段并进行高通量测序。4D核体计划包括图谱绘制等三个部分。"}, "cards": [{"front": "人类微生物组计划（HMP）主要包括哪些部位？", "back": "人类鼻腔、口腔、皮肤、胃肠道和泌尿生殖道的宏基因组样本数据和分析流程。", "mnemonic": "鼻腔、口腔、皮肤、胃肠道、泌尿生殖道", "useImg": false}]}, {"i": 18, "sec": "第五节 生物信息学新技术与发展趋势", "title": "4D核体计划与Hi-C技术流程", "notes": "本页属于‘第五节 生物信息学新技术与发展趋势’，重点介绍4D核体计划及Hi-C技术。4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范，建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响。图示图14-12展示Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段并进行高通量测序。图14-13展示4D核体计划的三个部分：图谱绘制（联结及动态的分子遗传学图谱）、模型建立（约束模型和分子遗传学模型）、功能验证（遗传学和生物物理验证）。该计划体现生物学研究目标动态化，结合3D基因组精准研究，用时间序列数据推断基因组动态改变，目标是构建细胞核的4D模型。", "page": 347, "level": "理解", "img": "assets/img/ch14/p347.jpg", "anim": null, "fig": "图14-12展示Hi-C技术流程。看图时注意从交联、酶切、标记、连接、纯化到片段化的步骤，理解Hi-C用于研究三维基因组结构。", "points": ["4D核体计划旨在定义细胞核结构与基因组组织的术语和数据类型规范", "建立细胞核的全面综合模型，探索核结构形成原理及其对生命活动的影响", "图14-12展示Hi-C技术流程：先用甲醛交联并分离染色质，再酶切并用生物素标记", "连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段"], "check": {"q": "关于新技术相互关系与生物信息学挑战，下列哪项说法正确？", "o": ["A. 第三代单分子测序不能免去单细胞测序中的扩增步骤", "B. 单细胞测序不能辅助宏基因组测序", "C. Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装", "D. 高通量测序不带来数据存储管理挑战"], "a": "C", "e": "第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性；单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现；Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装。高通量测序带来数据存储管理、比较分析、可视化等挑战。"}, "cards": [{"front": "Hi-C技术流程的主要步骤是什么？", "back": "先用甲醛交联并分离染色质，再酶切并用生物素标记，连接DNA并纯化，移除末端生物素并片段化，最后用生物素拉下片段。", "mnemonic": "交联→酶切→标记→连接→纯化→片段化→拉下", "useImg": false}]}, {"i": 19, "sec": "第五节 生物信息学新技术与发展趋势", "title": "新技术相互关系与生物信息学挑战", "notes": "本页总结新技术之间的相互关系及生物信息学挑战。第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性；单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现；Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装。实验方法日益强大，计算方法也快速发展。高通量测序带来数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难以长期保存，可舍弃；序列数据需长期持有。基因组比对需新算法，要求更准确快速、灵活、硬件要求低、容错。多倍体、高重复序列物种全基因组测序拼接难度大。数据质量控制、数千个富集区域可视化也是挑战。页末列出复习题，涉及第二代测序技术异同、优势、常见平台、Roche 454和Illumina Genome Analyzer测序原理等。", "page": 348, "level": "掌握", "img": "assets/img/ch14/p348.jpg", "anim": null, "fig": null, "points": ["第三代单分子测序可免去单细胞测序中的扩增步骤，提高测序精确性", "单细胞测序可辅助宏基因组测序，如新细菌Candidatus kryptonia的发现", "Hi-C技术可帮助宏基因组测序中不同微生物基因组的组装", "实验方法日益强大，计算方法也快速发展", "高通量测序带来数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难处理"], "check": {"q": "第十四章参考文献中，Mardis ER于2008年发表的文献主题是什么？", "o": ["A. RNA-Seq分析的进展", "B. 下一代DNA测序方法及其对遗传学的影响", "C. 人类微生物组研究框架", "D. 新测序技术在转录组分析中的应用"], "a": "B", "e": "参考文献列表中，Mardis ER 2008年发表的是关于下一代DNA测序方法及其对遗传学影响的文献。Haas BJ和Zody MC 2010年发表RNA-Seq分析的进展；Methée BA等2012年发表人类微生物组研究框架；Morozova O等2009年发表新测序技术在转录组分析中的应用。"}, "cards": [{"front": "高通量测序带来的生物信息学挑战有哪些？", "back": "数据存储管理、比较分析、可视化等挑战：原始图像数据量大，难处理。", "mnemonic": "存储、比较、可视化", "useImg": false}]}, {"i": 20, "sec": "第五节 生物信息学新技术与发展趋势", "title": "参考文献", "notes": "本页为第十四章参考文献列表，列出与新一代测序技术及其应用相关的文献，包括Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展、Horner DS等2010年关于下一代测序的基因组学和后基因组学应用生物信息学方法、Mardis ER 2008年关于下一代DNA测序方法及其对遗传学影响、Methée BA等2012年人类微生物组研究框架、Morozova O等2009年新测序技术在转录组分析中的应用等。这些文献为本章内容提供学术支撑，涉及RNA-Seq分析、测序方法、微生物组、转录组分析等方向。学习时可作为扩展阅读，了解新一代测序技术的应用背景和发展趋势。", "page": 349, "level": "了解", "img": "assets/img/ch14/p349.jpg", "anim": null, "fig": null, "points": ["第十四章参考文献列表", "列出与新一代测序技术及其应用相关的文献", "包括Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展", "Horner DS等2010年关于下一代测序的基因组学和后基因组学应用生物信息学方法", "Mardis ER 2008年关于下一代DNA测序方法及其对遗传学影响等"], "check": {"q": "关于文档生成信息页，下列哪项说法正确？", "o": ["A. 该页包含重要的生物信息学专业知识", "B. 该页为Anna's Archive生成的文档信息页，包含PDF附件统计信息，非教材正文内容", "C. 该页是第十四章的核心内容", "D. 学习时必须仔细研究该页的技术细节"], "a": "B", "e": "该页为Anna's Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。该页非教材正文内容，属于扫描版电子书的元数据页，学习时无需关注具体技术细节。"}, "cards": [{"front": "第十四章参考文献中包括哪些关于RNA-Seq分析的文献？", "back": "Haas BJ和Zody MC 2010年关于RNA-Seq分析的进展。", "mnemonic": "Haas & Zody 2010", "useImg": false}]}, {"i": 21, "sec": "第五节 生物信息学新技术与发展趋势", "title": "文档生成信息", "notes": "本页为Anna’s Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。该页非教材正文内容，属于扫描版电子书的元数据页。学习时无需关注具体技术细节，仅需了解该页为文档来源和统计信息，不涉及生物信息学专业知识。若用于自学，可跳过此页，直接关注前几页的4D核体计划、Hi-C技术流程、新技术相互关系及生物信息学挑战等内容。", "page": 350, "level": "了解", "img": "assets/img/ch14/p350.jpg", "anim": null, "fig": null, "points": ["Anna’s Archive生成的文档信息页", "包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等", "该页非教材正文内容，属于扫描版电子书的元数据页", "学习时无需关注具体技术细节，仅需了解该页为文档来源和统计信息", "若用于自学，可跳过此页"], "check": null, "cards": [{"front": "第350页的主要内容是什么？", "back": "Anna’s Archive生成的文档信息页，包含PDF附件中的统计信息，如文件名、文件大小、MD5、SHA1、SHA256、CRC32、解压后大小、页数等。非教材正文内容。", "mnemonic": "文档元数据页，可跳过", "useImg": false}]}], "mcq": [{"id": "ch14_mcq_1", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "下列关于Sanger测序的描述，正确的是：", "o": ["A. 它属于第二代测序技术，主要特点是高通量短读长", "B. 它利用ddNTP终止DNA链延伸，准确率高但通量低", "C. 它完全不需要电泳分离即可读取碱基序列", "D. 它主要依赖桥式PCR进行信号放大"], "a": "B", "e": "Sanger测序属于第一代测序，核心是双脱氧终止法，利用ddNTP终止延伸，通过电泳分离荧光标记片段。其准确率高、读长长，但通量低、成本高。桥式PCR是Illumina二代测序的扩增方式。", "kp": "ch14_s0_0"}, {"id": "ch14_mcq_2", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Roche 454测序平台的核心测序原理是：", "o": ["A. 桥式PCR结合可逆终止子合成测序", "B. 大规模并行焦磷酸合成测序", "C. 基于磁珠的克隆连接DNA测序", "D. 纳米孔单分子测序"], "a": "B", "e": "Roche/454采用大规模并行焦磷酸合成测序。dNTP掺入释放焦磷酸，经APS生成ATP，荧光素酶催化发光。Illumina采用桥式PCR和可逆终止子，SOLiD采用连接测序，纳米孔属于三代测序。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_3", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina Solexa测序中，桥式PCR的主要作用是：", "o": ["A. 将RNA直接转化为蛋白质", "B. 在固相表面扩增DNA片段形成克隆簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 利用连接酶读取双碱基编码"], "a": "B", "e": "Illumina平台通过桥式PCR在固相表面扩增DNA片段，形成空间分离的克隆簇，再进行合成测序。RNA直接转蛋白质不是测序步骤；重硫酸盐处理用于甲基化研究；连接酶和双碱基编码属于SOLiD。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_4", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "ABI SOLiD测序中“双碱基编码”的主要优点是：", "o": ["A. 使读长达到1000 bp以上", "B. 每个碱基被判读两次，降低原始数据错误", "C. 完全不需要参考基因组即可组装", "D. 可直接测RNA而不需反转录"], "a": "B", "e": "SOLiD采用双碱基编码，每个碱基被判读两次，因此可减少原始数据错误，准确度较高。其读长较短，约35 bp，仍需建库和测序，不能直接测RNA。", "kp": "ch14_s0_5"}, {"id": "ch14_mcq_5", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "全基因组重测序（re-sequencing）通常用于：", "o": ["A. 对未知基因组物种进行从头组装", "B. 对已有参考基因组的个体进行差异分析", "C. 只检测DNA甲基化水平", "D. 只定量小非编码RNA表达"], "a": "B", "e": "全基因组重测序是对已知参考基因组的物种进行不同个体测序，通过比对发现SNP、InDel和结构变异等。从头组装适用于无参考基因组；甲基化和小RNA分析分别属于表观组学和smRNA-seq。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_6", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "RNA-seq通常测序的对象是：", "o": ["A. 直接测序原始RNA分子", "B. 反转录得到的cDNA文库", "C. 只测序蛋白质", "D. 只测序甲基化DNA"], "a": "B", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建cDNA文库后测序，从而推断RNA信息。它不是直接测RNA，也不是测蛋白质或甲基化DNA。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_7", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于ChIP-seq，下列描述正确的是：", "o": ["A. 用于研究蛋白质与DNA的结合位点", "B. 用于检测SNP和InDel", "C. 用于测定宏基因组物种多样性", "D. 用于单细胞全基因组扩增"], "a": "A", "e": "ChIP-seq即染色质免疫共沉淀测序，通过抗体富集与蛋白质结合的DNA片段，再测序定位结合位点或组蛋白修饰区域。SNP/InDel检测常由重测序完成；宏基因组和单细胞测序是其他方向。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_8", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "重硫酸盐测序（bisulfite sequencing）的原理是：", "o": ["A. 甲基化胞嘧啶转化为尿嘧啶，未甲基化胞嘧啶不变", "B. 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变", "C. 所有胞嘧啶都转化为腺嘌呤", "D. 所有鸟嘌呤都转化为胸腺嘧啶"], "a": "B", "e": "重硫酸盐处理使未甲基化胞嘧啶转化为尿嘧啶，而甲基化胞嘧啶保持不变，从而区分甲基化状态。5hmC也会抵抗转化，需用oxBS-seq、TAB-seq等方法进一步区分。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_9", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在NGS差异表达分析中，单因素两组数据常用的统计方法是：", "o": ["A. t检验", "B. two-way ANOVA", "C. 隐马尔可夫模型", "D. 纳米孔测序"], "a": "A", "e": "单因素两组数据常用t检验，计算P值并筛选显著差异基因。单因素多组用one-way ANOVA，多因素用two-way ANOVA。隐马尔可夫模型属于机器学习/序列分析方法，纳米孔测序是测序技术。", "kp": "ch14_s0_10"}, {"id": "ch14_mcq_10", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于宏基因组学，下列描述正确的是：", "o": ["A. 只研究可纯培养的微生物", "B. 以某一环境中全体微生物基因组为研究对象", "C. 只能基于16S rRNA，不能进行全基因组测序", "D. 主要用于单细胞转录组分析"], "a": "B", "e": "宏基因组学以环境中全体微生物基因组为研究对象，可分析群落多样性、结构和功能。它突破了传统纯培养限制，最初常用16S rRNA，后来可发展到全基因组测序分析。单细胞转录组属于单细胞组学。", "kp": "ch14_s0_16"}], "judge": [{"id": "ch14_judge_1", "modI": 0, "q": "Sanger测序是第一代测序的代表，其读长可达约1000 bp，单碱基准确率可达99.999%。", "a": "对", "e": "Sanger测序又称双脱氧终止法，读长长、准确率高，是人类基因组计划主要依赖的技术。", "kp": "ch14_s0_0"}, {"id": "ch14_judge_2", "modI": 0, "q": "第二代测序多数仍依赖PCR扩增，而三代测序强调单分子、无需扩增。", "a": "对", "e": "二代测序通过乳液PCR或桥式PCR等方式生成克隆阵列；三代测序强调单分子读取，无需PCR扩增。", "kp": "ch14_s0_1"}, {"id": "ch14_judge_3", "modI": 0, "q": "Roche 454焦磷酸测序的主要错误类型为替换（Substitution），尤其在同聚物区域容易产生误差。", "a": "错", "e": "Roche 454的主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差；替换为主是Illumina等平台的错误特征。", "kp": "ch14_s0_2"}, {"id": "ch14_judge_4", "modI": 0, "q": "Illumina/Solexa平台采用桥式PCR在固相表面扩增DNA片段，形成克隆簇。", "a": "对", "e": "Illumina/Solexa平台采用桥式PCR，测序时使用可逆终止子标记的dNTP，每轮只掺入一个碱基。", "kp": "ch14_s0_4"}, {"id": "ch14_judge_5", "modI": 0, "q": "ABI SOLiD平台使用DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "a": "错", "e": "ABI SOLiD平台使用连接酶而非DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "kp": "ch14_s0_6"}, {"id": "ch14_judge_6", "modI": 0, "q": "RNA-seq通常直接测RNA，而不是测cDNA。", "a": "错", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序，因此测的是cDNA。", "kp": "ch14_s0_12"}, {"id": "ch14_judge_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变。", "a": "对", "e": "这是重硫酸盐测序的经典原理，用于研究DNA甲基化。", "kp": "ch14_s0_9"}, {"id": "ch14_judge_8", "modI": 0, "q": "ChIP-seq通过抗体特异性富集与蛋白质结合的DNA片段，再高通量测序，用于定位转录因子结合位点或组蛋白修饰区域。", "a": "对", "e": "ChIP-seq是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_judge_9", "modI": 0, "q": "单细胞测序结果反映细胞群体平均信号，可能掩盖细胞异质性。", "a": "错", "e": "传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；单细胞测序可在单细胞水平检测基因组和转录组，揭示细胞异质性。", "kp": "ch14_s0_15"}, {"id": "ch14_judge_10", "modI": 0, "q": "宏基因组学以某一环境中全体微生物基因组为研究对象，突破了传统微生物研究依赖纯培养的瓶颈。", "a": "对", "e": "自然界约99%微生物不可培养，宏基因组学利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。", "kp": "ch14_s0_16"}], "fill": [{"id": "ch14_fill_1", "modI": 0, "q": "Sanger测序又称________，其核心是利用________终止DNA链延伸。", "a": "双脱氧终止法,ddNTP", "kp": "ch14_s0_0"}, {"id": "ch14_fill_2", "modI": 0, "q": "第二代测序以________、________为特征，代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等。", "a": "高通量,短读长", "kp": "ch14_s0_4"}, {"id": "ch14_fill_3", "modI": 0, "q": "Roche 454焦磷酸测序中，DNA聚合酶催化dNTP掺入时释放________；焦磷酸与APS结合生成________；荧光素酶催化荧光素氧化并发出荧光。", "a": "焦磷酸,ATP", "kp": "ch14_s0_2"}, {"id": "ch14_fill_4", "modI": 0, "q": "Illumina/Solexa平台采用________在固相表面扩增DNA片段，形成克隆簇；测序时使用可逆终止子标记的dNTP，每轮只掺入________个碱基。", "a": "桥式PCR,一", "kp": "ch14_s0_4"}, {"id": "ch14_fill_5", "modI": 0, "q": "ABI SOLiD平台采用________策略，每个碱基被判读________次，因此可降低原始数据错误。", "a": "双碱基编码,两", "kp": "ch14_s0_7"}, {"id": "ch14_fill_6", "modI": 0, "q": "RNA-seq通常先将mRNA分离并反转录为________，构建片段化cDNA文库后进行高通量测序，因此RNA-seq不是直接测RNA，而是测________。", "a": "cDNA,cDNA", "kp": "ch14_s0_8"}, {"id": "ch14_fill_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为________，甲基化胞嘧啶________。", "a": "尿嘧啶,不变", "kp": "ch14_s0_9"}, {"id": "ch14_fill_8", "modI": 0, "q": "NCBI建立了新一代测序结果子数据库________，用于存储高通量测序数据；常用公共数据库还包括EBI ENA和DDBJ DTA等。", "a": "SRA", "kp": "ch14_s0_10"}], "short": [{"id": "ch14_short_1", "modI": 0, "q": "简述Sanger测序的基本原理及其优缺点。", "a": "原理：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列。优点：1) 读长长，可达约1000 bp；2) 准确率高，单碱基准确率可达99.999%；3) 可靠性强，适合完成精细测序和验证。缺点：1) 通量低；2) 成本高；3) 耗时长。", "kp": "ch14_s0_0"}, {"id": "ch14_short_2", "modI": 0, "q": "简述第二代测序的基本流程和核心优势。", "a": "基本流程：1) 将基因组DNA片段化；2) 两端连接接头；3) 通过乳液PCR或桥式PCR等方式生成空间固定的克隆阵列；4) 在同一平面上进行大规模并行延伸和成像检测。核心优势：1) 并行处理能力强；2) 通量高；3) 灵敏度高；4) 运行成本低。", "kp": "ch14_s0_1"}, {"id": "ch14_short_3", "modI": 0, "q": "简述RNA-seq的优势及分析重点。", "a": "优势：1) 通量高；2) 覆盖广；3) 精度高；4) 不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定。分析重点：1) 比对；2) 表达定量；3) 差异表达；4) 可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_short_4", "modI": 0, "q": "简述ChIP-seq的原理和用途。", "a": "原理：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序。用途：1) 定位转录因子结合位点；2) 定位组蛋白修饰区域；3) 研究染色质状态和表观组学。", "kp": "ch14_s0_8"}, {"id": "ch14_short_5", "modI": 0, "q": "简述单细胞测序的意义和基本流程。", "a": "意义：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) 单细胞测序可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型。基本流程：1) 单细胞分离；2) 裂解；3) 逆转录；4) 扩增；5) 文库构建；6) 高通量测序。", "kp": "ch14_s0_16"}], "calc": [{"id": "ch14_calc_1", "modI": 0, "q": "论述NGS在功能基因组学中的综合应用及主要挑战。", "a": "NGS可产生基因水平、转录水平和蛋白质水平等多层次数据。功能基因组学综合研究强调将DNA-seq、RNA-seq、ChIP-seq、表观组学等数据整合，进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建。通过多重相关性、多重实验和网络重建，可更全面理解生物学机制。主要挑战包括数据异质性、批次效应、多组学整合算法和结果可解释性。其目标是实现精准化、全面化和动态化的生物学研究。", "steps": "1) 明确多组学数据类型；2) 整合DNA-seq、RNA-seq、ChIP-seq、表观组学等；3) 进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建；4) 利用多重相关性、多重实验和网络重建理解机制；5) 关注数据异质性、批次效应、多组学整合算法和结果可解释性；6) 目标为精准化、全面化和动态化研究。", "kp": "ch14_s0_15"}, {"id": "ch14_calc_2", "modI": 0, "q": "论述宏基因组学的研究对象、意义和一般流程。", "a": "宏基因组学以某一环境中全体微生物基因组为研究对象，利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。传统微生物研究依赖纯培养，但自然界约99%微生物不可培养，宏基因组学突破了这一瓶颈。最初研究常基于保守16S rRNA分析，后来发展到对环境全体微生物全部基因组测序分析。宏基因组广泛应用于海洋、土壤、肠道菌群、感染性疾病等领域。一般流程包括环境样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "steps": "1) 研究对象为环境中全体微生物基因组；2) 分析多样性、种群结构、功能活性和相互作用；3) 突破纯培养限制，因约99%微生物不可培养；4) 从16S rRNA分析发展到全基因组测序分析；5) 应用于海洋、土壤、肠道菌群、感染性疾病等；6) 流程包括样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "kp": "ch14_s0_16"}], "term": [{"id": "ch14_term_1", "modI": 0, "term": "Sanger sequencing", "def": "又称双脱氧终止法，是第一代测序的代表技术。要点：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列；4) 读长长，可达约1000 bp；5) 单碱基准确率可达99.999%；6) 通量低、成本高、速度慢；7) 人类基因组计划主要依赖该技术。", "kp": "ch14_s0_0"}, {"id": "ch14_term_2", "modI": 0, "term": "Next-generation sequencing (NGS)", "def": "第二代测序技术，以高通量、短读长为特征。要点：1) 基本流程包括DNA片段化、连接接头、乳液PCR或桥式PCR生成克隆阵列、大规模并行延伸和成像检测；2) 核心优势是并行处理能力强、通量高、灵敏度高、运行成本低；3) 读长差异较大，约13–450 bp；4) 单次实验可产生高达100 Gb碱基数据；5) 代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等；6) 多数仍依赖PCR扩增。", "kp": "ch14_s0_4"}, {"id": "ch14_term_3", "modI": 0, "term": "Third-generation sequencing", "def": "第三代测序技术，强调单分子读取。要点：1) 无需PCR扩增；2) 代表技术包括Helicos、PacBio SMRT和Oxford Nanopore；3) 核心指标包括读长、通量、是否依赖扩增、单分子能力；4) 可克服二代测序扩增偏差和短读长限制。", "kp": "ch14_s0_4"}, {"id": "ch14_term_4", "modI": 0, "term": "Pyrosequencing", "def": "Roche 454平台采用的焦磷酸合成测序原理。要点：1) DNA聚合酶催化dNTP掺入时释放焦磷酸；2) 焦磷酸与APS结合生成ATP；3) 荧光素酶催化荧光素氧化并发出荧光，报告碱基掺入事件；4) 通常采用乳液PCR，将DNA片段固定在磁珠上并在油包水小滴中扩增；5) 读长相对较长，约250 bp；6) 主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差。", "kp": "ch14_s0_8"}, {"id": "ch14_term_5", "modI": 0, "term": "Bridge PCR", "def": "Illumina/Solexa平台采用的固相表面扩增方法。要点：1) 在固相表面扩增DNA片段，形成克隆簇；2) 测序时使用可逆终止子标记的dNTP；3) 每轮只掺入一个碱基，通过荧光成像识别碱基类型；4) 切除荧光基团和终止基团后进入下一轮延伸；5) 读长较短，早期约36 bp，但通量极高、成本低；6) 错误类型以替换（Substitution）为主，随读长增加末端质量下降。", "kp": "ch14_s0_3"}, {"id": "ch14_term_6", "modI": 0, "term": "Two-base encoding", "def": "ABI SOLiD平台采用的双碱基编码策略。要点：1) 使用连接酶而非DNA聚合酶进行测序；2) 原始数据由四种颜色编码组成；3) 每个碱基被判读两次，可降低原始数据错误；4) 准确度可大于99.94%；5) 数据分析时需按照双碱基编码矩阵将颜色序列解码为碱基序列；6) 若已知任一位置碱基类型，即可推导整段颜色序列对应的碱基序列；7) 读长较短，约35 bp，错误类型以替换为主。", "kp": "ch14_s0_4"}, {"id": "ch14_term_7", "modI": 0, "term": "Whole-genome resequencing", "def": "对已有参考基因组的物种进行不同个体测序，并与参考基因组比对，从而发现个体或群体差异。要点：1) 可检测单核苷酸多态性（SNP）、插入缺失（InDel）和结构变异（SV）；2) 高通量测序可减少传统文库构建和亚克隆偏差；3) 数据分析依赖参考基因组和比对算法；4) 关键步骤包括读长质控、比对、变异检测、注释和群体分析。", "kp": "ch14_s0_4"}, {"id": "ch14_term_8", "modI": 0, "term": "RNA-seq", "def": "转录组测序技术。要点：1) 转录组是特定细胞或组织在某一功能状态下转录出的全部RNA，包括mRNA和非编码RNA；2) 通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序；3) RNA-seq不是直接测RNA，而是测cDNA；4) 优势包括通量高、覆盖广、精度高、不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定；6) 分析重点包括比对、表达定量、差异表达和可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_9", "modI": 0, "term": "smRNA-seq", "def": "小非编码RNA测序技术。要点：1) 主要针对18–30 nt的小非编码RNA，如microRNA、tasiRNA和piRNA；2) 实验流程通常从总RNA中分离small RNA，两端加接头，反转录为cDNA，再测序；3) 分析可获得全基因组microRNA图谱；4) 用于新microRNA鉴定、差异表达、聚类和表达谱分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_10", "modI": 0, "term": "ChIP-seq", "def": "染色质免疫共沉淀测序。要点：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序；3) 用于定位转录因子结合位点或组蛋白修饰区域；4) 是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_term_11", "modI": 0, "term": "Bisulfite sequencing", "def": "重硫酸盐测序，DNA甲基化研究的经典方法。要点：1) 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变；2) 常见方法包括全基因组重硫酸盐测序（MethylC-seq/BS-seq）和简化表达重硫酸盐测序（RRBS）；3) 5hmC也会抵抗重硫酸盐转化；4) 可用hMeDIP-seq、oxBS-seq或TAB-seq等方法区分5hmC。", "kp": "ch14_s0_4"}, {"id": "ch14_term_12", "modI": 0, "term": "Single-cell sequencing (SCS)", "def": "单细胞测序技术。要点：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) SCS可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型；4) 流程一般包括单细胞分离、裂解、逆转录、扩增、文库构建和高通量测序；5) 在癌症、免疫治疗、循环肿瘤细胞（CTC）和早期胚胎细胞研究中意义重大；6) 2016年启动的人类细胞图谱计划是重要代表。", "kp": "ch14_s0_4"}]}], "mcq": [{"id": "ch14_mcq_1", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "下列关于Sanger测序的描述，正确的是：", "o": ["A. 它属于第二代测序技术，主要特点是高通量短读长", "B. 它利用ddNTP终止DNA链延伸，准确率高但通量低", "C. 它完全不需要电泳分离即可读取碱基序列", "D. 它主要依赖桥式PCR进行信号放大"], "a": "B", "e": "Sanger测序属于第一代测序，核心是双脱氧终止法，利用ddNTP终止延伸，通过电泳分离荧光标记片段。其准确率高、读长长，但通量低、成本高。桥式PCR是Illumina二代测序的扩增方式。", "kp": "ch14_s0_0"}, {"id": "ch14_mcq_2", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Roche 454测序平台的核心测序原理是：", "o": ["A. 桥式PCR结合可逆终止子合成测序", "B. 大规模并行焦磷酸合成测序", "C. 基于磁珠的克隆连接DNA测序", "D. 纳米孔单分子测序"], "a": "B", "e": "Roche/454采用大规模并行焦磷酸合成测序。dNTP掺入释放焦磷酸，经APS生成ATP，荧光素酶催化发光。Illumina采用桥式PCR和可逆终止子，SOLiD采用连接测序，纳米孔属于三代测序。", "kp": "ch14_s0_2"}, {"id": "ch14_mcq_3", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "Illumina Solexa测序中，桥式PCR的主要作用是：", "o": ["A. 将RNA直接转化为蛋白质", "B. 在固相表面扩增DNA片段形成克隆簇", "C. 将甲基化胞嘧啶转化为尿嘧啶", "D. 利用连接酶读取双碱基编码"], "a": "B", "e": "Illumina平台通过桥式PCR在固相表面扩增DNA片段，形成空间分离的克隆簇，再进行合成测序。RNA直接转蛋白质不是测序步骤；重硫酸盐处理用于甲基化研究；连接酶和双碱基编码属于SOLiD。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_4", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "ABI SOLiD测序中“双碱基编码”的主要优点是：", "o": ["A. 使读长达到1000 bp以上", "B. 每个碱基被判读两次，降低原始数据错误", "C. 完全不需要参考基因组即可组装", "D. 可直接测RNA而不需反转录"], "a": "B", "e": "SOLiD采用双碱基编码，每个碱基被判读两次，因此可减少原始数据错误，准确度较高。其读长较短，约35 bp，仍需建库和测序，不能直接测RNA。", "kp": "ch14_s0_5"}, {"id": "ch14_mcq_5", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "全基因组重测序（re-sequencing）通常用于：", "o": ["A. 对未知基因组物种进行从头组装", "B. 对已有参考基因组的个体进行差异分析", "C. 只检测DNA甲基化水平", "D. 只定量小非编码RNA表达"], "a": "B", "e": "全基因组重测序是对已知参考基因组的物种进行不同个体测序，通过比对发现SNP、InDel和结构变异等。从头组装适用于无参考基因组；甲基化和小RNA分析分别属于表观组学和smRNA-seq。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_6", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "RNA-seq通常测序的对象是：", "o": ["A. 直接测序原始RNA分子", "B. 反转录得到的cDNA文库", "C. 只测序蛋白质", "D. 只测序甲基化DNA"], "a": "B", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建cDNA文库后测序，从而推断RNA信息。它不是直接测RNA，也不是测蛋白质或甲基化DNA。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_7", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于ChIP-seq，下列描述正确的是：", "o": ["A. 用于研究蛋白质与DNA的结合位点", "B. 用于检测SNP和InDel", "C. 用于测定宏基因组物种多样性", "D. 用于单细胞全基因组扩增"], "a": "A", "e": "ChIP-seq即染色质免疫共沉淀测序，通过抗体富集与蛋白质结合的DNA片段，再测序定位结合位点或组蛋白修饰区域。SNP/InDel检测常由重测序完成；宏基因组和单细胞测序是其他方向。", "kp": "ch14_s0_8"}, {"id": "ch14_mcq_8", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "重硫酸盐测序（bisulfite sequencing）的原理是：", "o": ["A. 甲基化胞嘧啶转化为尿嘧啶，未甲基化胞嘧啶不变", "B. 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变", "C. 所有胞嘧啶都转化为腺嘌呤", "D. 所有鸟嘌呤都转化为胸腺嘧啶"], "a": "B", "e": "重硫酸盐处理使未甲基化胞嘧啶转化为尿嘧啶，而甲基化胞嘧啶保持不变，从而区分甲基化状态。5hmC也会抵抗转化，需用oxBS-seq、TAB-seq等方法进一步区分。", "kp": "ch14_s0_4"}, {"id": "ch14_mcq_9", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "在NGS差异表达分析中，单因素两组数据常用的统计方法是：", "o": ["A. t检验", "B. two-way ANOVA", "C. 隐马尔可夫模型", "D. 纳米孔测序"], "a": "A", "e": "单因素两组数据常用t检验，计算P值并筛选显著差异基因。单因素多组用one-way ANOVA，多因素用two-way ANOVA。隐马尔可夫模型属于机器学习/序列分析方法，纳米孔测序是测序技术。", "kp": "ch14_s0_10"}, {"id": "ch14_mcq_10", "mod": "第十四章 新一代测序技术及其应用", "modI": 0, "q": "关于宏基因组学，下列描述正确的是：", "o": ["A. 只研究可纯培养的微生物", "B. 以某一环境中全体微生物基因组为研究对象", "C. 只能基于16S rRNA，不能进行全基因组测序", "D. 主要用于单细胞转录组分析"], "a": "B", "e": "宏基因组学以环境中全体微生物基因组为研究对象，可分析群落多样性、结构和功能。它突破了传统纯培养限制，最初常用16S rRNA，后来可发展到全基因组测序分析。单细胞转录组属于单细胞组学。", "kp": "ch14_s0_16"}], "judge": [{"id": "ch14_judge_1", "modI": 0, "q": "Sanger测序是第一代测序的代表，其读长可达约1000 bp，单碱基准确率可达99.999%。", "a": "对", "e": "Sanger测序又称双脱氧终止法，读长长、准确率高，是人类基因组计划主要依赖的技术。", "kp": "ch14_s0_0"}, {"id": "ch14_judge_2", "modI": 0, "q": "第二代测序多数仍依赖PCR扩增，而三代测序强调单分子、无需扩增。", "a": "对", "e": "二代测序通过乳液PCR或桥式PCR等方式生成克隆阵列；三代测序强调单分子读取，无需PCR扩增。", "kp": "ch14_s0_1"}, {"id": "ch14_judge_3", "modI": 0, "q": "Roche 454焦磷酸测序的主要错误类型为替换（Substitution），尤其在同聚物区域容易产生误差。", "a": "错", "e": "Roche 454的主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差；替换为主是Illumina等平台的错误特征。", "kp": "ch14_s0_2"}, {"id": "ch14_judge_4", "modI": 0, "q": "Illumina/Solexa平台采用桥式PCR在固相表面扩增DNA片段，形成克隆簇。", "a": "对", "e": "Illumina/Solexa平台采用桥式PCR，测序时使用可逆终止子标记的dNTP，每轮只掺入一个碱基。", "kp": "ch14_s0_4"}, {"id": "ch14_judge_5", "modI": 0, "q": "ABI SOLiD平台使用DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "a": "错", "e": "ABI SOLiD平台使用连接酶而非DNA聚合酶进行测序，原始数据由四种颜色编码组成。", "kp": "ch14_s0_6"}, {"id": "ch14_judge_6", "modI": 0, "q": "RNA-seq通常直接测RNA，而不是测cDNA。", "a": "错", "e": "RNA-seq通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序，因此测的是cDNA。", "kp": "ch14_s0_12"}, {"id": "ch14_judge_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变。", "a": "对", "e": "这是重硫酸盐测序的经典原理，用于研究DNA甲基化。", "kp": "ch14_s0_9"}, {"id": "ch14_judge_8", "modI": 0, "q": "ChIP-seq通过抗体特异性富集与蛋白质结合的DNA片段，再高通量测序，用于定位转录因子结合位点或组蛋白修饰区域。", "a": "对", "e": "ChIP-seq是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_judge_9", "modI": 0, "q": "单细胞测序结果反映细胞群体平均信号，可能掩盖细胞异质性。", "a": "错", "e": "传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；单细胞测序可在单细胞水平检测基因组和转录组，揭示细胞异质性。", "kp": "ch14_s0_15"}, {"id": "ch14_judge_10", "modI": 0, "q": "宏基因组学以某一环境中全体微生物基因组为研究对象，突破了传统微生物研究依赖纯培养的瓶颈。", "a": "对", "e": "自然界约99%微生物不可培养，宏基因组学利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。", "kp": "ch14_s0_16"}], "fill": [{"id": "ch14_fill_1", "modI": 0, "q": "Sanger测序又称________，其核心是利用________终止DNA链延伸。", "a": "双脱氧终止法,ddNTP", "kp": "ch14_s0_0"}, {"id": "ch14_fill_2", "modI": 0, "q": "第二代测序以________、________为特征，代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等。", "a": "高通量,短读长", "kp": "ch14_s0_4"}, {"id": "ch14_fill_3", "modI": 0, "q": "Roche 454焦磷酸测序中，DNA聚合酶催化dNTP掺入时释放________；焦磷酸与APS结合生成________；荧光素酶催化荧光素氧化并发出荧光。", "a": "焦磷酸,ATP", "kp": "ch14_s0_2"}, {"id": "ch14_fill_4", "modI": 0, "q": "Illumina/Solexa平台采用________在固相表面扩增DNA片段，形成克隆簇；测序时使用可逆终止子标记的dNTP，每轮只掺入________个碱基。", "a": "桥式PCR,一", "kp": "ch14_s0_4"}, {"id": "ch14_fill_5", "modI": 0, "q": "ABI SOLiD平台采用________策略，每个碱基被判读________次，因此可降低原始数据错误。", "a": "双碱基编码,两", "kp": "ch14_s0_7"}, {"id": "ch14_fill_6", "modI": 0, "q": "RNA-seq通常先将mRNA分离并反转录为________，构建片段化cDNA文库后进行高通量测序，因此RNA-seq不是直接测RNA，而是测________。", "a": "cDNA,cDNA", "kp": "ch14_s0_8"}, {"id": "ch14_fill_7", "modI": 0, "q": "重硫酸盐测序中，未甲基化胞嘧啶转化为________，甲基化胞嘧啶________。", "a": "尿嘧啶,不变", "kp": "ch14_s0_9"}, {"id": "ch14_fill_8", "modI": 0, "q": "NCBI建立了新一代测序结果子数据库________，用于存储高通量测序数据；常用公共数据库还包括EBI ENA和DDBJ DTA等。", "a": "SRA", "kp": "ch14_s0_10"}], "short": [{"id": "ch14_short_1", "modI": 0, "q": "简述Sanger测序的基本原理及其优缺点。", "a": "原理：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列。优点：1) 读长长，可达约1000 bp；2) 准确率高，单碱基准确率可达99.999%；3) 可靠性强，适合完成精细测序和验证。缺点：1) 通量低；2) 成本高；3) 耗时长。", "kp": "ch14_s0_0"}, {"id": "ch14_short_2", "modI": 0, "q": "简述第二代测序的基本流程和核心优势。", "a": "基本流程：1) 将基因组DNA片段化；2) 两端连接接头；3) 通过乳液PCR或桥式PCR等方式生成空间固定的克隆阵列；4) 在同一平面上进行大规模并行延伸和成像检测。核心优势：1) 并行处理能力强；2) 通量高；3) 灵敏度高；4) 运行成本低。", "kp": "ch14_s0_1"}, {"id": "ch14_short_3", "modI": 0, "q": "简述RNA-seq的优势及分析重点。", "a": "优势：1) 通量高；2) 覆盖广；3) 精度高；4) 不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定。分析重点：1) 比对；2) 表达定量；3) 差异表达；4) 可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_short_4", "modI": 0, "q": "简述ChIP-seq的原理和用途。", "a": "原理：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序。用途：1) 定位转录因子结合位点；2) 定位组蛋白修饰区域；3) 研究染色质状态和表观组学。", "kp": "ch14_s0_8"}, {"id": "ch14_short_5", "modI": 0, "q": "简述单细胞测序的意义和基本流程。", "a": "意义：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) 单细胞测序可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型。基本流程：1) 单细胞分离；2) 裂解；3) 逆转录；4) 扩增；5) 文库构建；6) 高通量测序。", "kp": "ch14_s0_16"}], "calc": [{"id": "ch14_calc_1", "modI": 0, "q": "论述NGS在功能基因组学中的综合应用及主要挑战。", "a": "NGS可产生基因水平、转录水平和蛋白质水平等多层次数据。功能基因组学综合研究强调将DNA-seq、RNA-seq、ChIP-seq、表观组学等数据整合，进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建。通过多重相关性、多重实验和网络重建，可更全面理解生物学机制。主要挑战包括数据异质性、批次效应、多组学整合算法和结果可解释性。其目标是实现精准化、全面化和动态化的生物学研究。", "steps": "1) 明确多组学数据类型；2) 整合DNA-seq、RNA-seq、ChIP-seq、表观组学等；3) 进行de novo组装、CNV分析、新转录本/基因座鉴定、SNP检测、可变剪切位点分析、通路分析和调控网络重建；4) 利用多重相关性、多重实验和网络重建理解机制；5) 关注数据异质性、批次效应、多组学整合算法和结果可解释性；6) 目标为精准化、全面化和动态化研究。", "kp": "ch14_s0_15"}, {"id": "ch14_calc_2", "modI": 0, "q": "论述宏基因组学的研究对象、意义和一般流程。", "a": "宏基因组学以某一环境中全体微生物基因组为研究对象，利用生物信息学分析微生物群落的多样性、种群结构、功能活性和相互作用。传统微生物研究依赖纯培养，但自然界约99%微生物不可培养，宏基因组学突破了这一瓶颈。最初研究常基于保守16S rRNA分析，后来发展到对环境全体微生物全部基因组测序分析。宏基因组广泛应用于海洋、土壤、肠道菌群、感染性疾病等领域。一般流程包括环境样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "steps": "1) 研究对象为环境中全体微生物基因组；2) 分析多样性、种群结构、功能活性和相互作用；3) 突破纯培养限制，因约99%微生物不可培养；4) 从16S rRNA分析发展到全基因组测序分析；5) 应用于海洋、土壤、肠道菌群、感染性疾病等；6) 流程包括样品采集、DNA提取、文库构建、高通量测序、组装、基因预测、物种注释和功能分析。", "kp": "ch14_s0_16"}], "term": [{"id": "ch14_term_1", "modI": 0, "term": "Sanger sequencing", "def": "又称双脱氧终止法，是第一代测序的代表技术。要点：1) 利用ddNTP终止DNA链延伸；2) 产生一系列长度不同的荧光标记片段；3) 通过毛细管电泳分离并读取碱基序列；4) 读长长，可达约1000 bp；5) 单碱基准确率可达99.999%；6) 通量低、成本高、速度慢；7) 人类基因组计划主要依赖该技术。", "kp": "ch14_s0_0"}, {"id": "ch14_term_2", "modI": 0, "term": "Next-generation sequencing (NGS)", "def": "第二代测序技术，以高通量、短读长为特征。要点：1) 基本流程包括DNA片段化、连接接头、乳液PCR或桥式PCR生成克隆阵列、大规模并行延伸和成像检测；2) 核心优势是并行处理能力强、通量高、灵敏度高、运行成本低；3) 读长差异较大，约13–450 bp；4) 单次实验可产生高达100 Gb碱基数据；5) 代表平台包括Roche 454、Illumina Solexa、ABI SOLiD等；6) 多数仍依赖PCR扩增。", "kp": "ch14_s0_4"}, {"id": "ch14_term_3", "modI": 0, "term": "Third-generation sequencing", "def": "第三代测序技术，强调单分子读取。要点：1) 无需PCR扩增；2) 代表技术包括Helicos、PacBio SMRT和Oxford Nanopore；3) 核心指标包括读长、通量、是否依赖扩增、单分子能力；4) 可克服二代测序扩增偏差和短读长限制。", "kp": "ch14_s0_4"}, {"id": "ch14_term_4", "modI": 0, "term": "Pyrosequencing", "def": "Roche 454平台采用的焦磷酸合成测序原理。要点：1) DNA聚合酶催化dNTP掺入时释放焦磷酸；2) 焦磷酸与APS结合生成ATP；3) 荧光素酶催化荧光素氧化并发出荧光，报告碱基掺入事件；4) 通常采用乳液PCR，将DNA片段固定在磁珠上并在油包水小滴中扩增；5) 读长相对较长，约250 bp；6) 主要错误类型为插入缺失（Indel），尤其在同聚物区域容易产生误差。", "kp": "ch14_s0_8"}, {"id": "ch14_term_5", "modI": 0, "term": "Bridge PCR", "def": "Illumina/Solexa平台采用的固相表面扩增方法。要点：1) 在固相表面扩增DNA片段，形成克隆簇；2) 测序时使用可逆终止子标记的dNTP；3) 每轮只掺入一个碱基，通过荧光成像识别碱基类型；4) 切除荧光基团和终止基团后进入下一轮延伸；5) 读长较短，早期约36 bp，但通量极高、成本低；6) 错误类型以替换（Substitution）为主，随读长增加末端质量下降。", "kp": "ch14_s0_3"}, {"id": "ch14_term_6", "modI": 0, "term": "Two-base encoding", "def": "ABI SOLiD平台采用的双碱基编码策略。要点：1) 使用连接酶而非DNA聚合酶进行测序；2) 原始数据由四种颜色编码组成；3) 每个碱基被判读两次，可降低原始数据错误；4) 准确度可大于99.94%；5) 数据分析时需按照双碱基编码矩阵将颜色序列解码为碱基序列；6) 若已知任一位置碱基类型，即可推导整段颜色序列对应的碱基序列；7) 读长较短，约35 bp，错误类型以替换为主。", "kp": "ch14_s0_4"}, {"id": "ch14_term_7", "modI": 0, "term": "Whole-genome resequencing", "def": "对已有参考基因组的物种进行不同个体测序，并与参考基因组比对，从而发现个体或群体差异。要点：1) 可检测单核苷酸多态性（SNP）、插入缺失（InDel）和结构变异（SV）；2) 高通量测序可减少传统文库构建和亚克隆偏差；3) 数据分析依赖参考基因组和比对算法；4) 关键步骤包括读长质控、比对、变异检测、注释和群体分析。", "kp": "ch14_s0_4"}, {"id": "ch14_term_8", "modI": 0, "term": "RNA-seq", "def": "转录组测序技术。要点：1) 转录组是特定细胞或组织在某一功能状态下转录出的全部RNA，包括mRNA和非编码RNA；2) 通常先将mRNA分离并反转录为cDNA，构建片段化cDNA文库后进行高通量测序；3) RNA-seq不是直接测RNA，而是测cDNA；4) 优势包括通量高、覆盖广、精度高、不依赖参考基因组；5) 可用于可变剪切、基因表达水平、新转录本和新基因鉴定；6) 分析重点包括比对、表达定量、差异表达和可变剪切分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_9", "modI": 0, "term": "smRNA-seq", "def": "小非编码RNA测序技术。要点：1) 主要针对18–30 nt的小非编码RNA，如microRNA、tasiRNA和piRNA；2) 实验流程通常从总RNA中分离small RNA，两端加接头，反转录为cDNA，再测序；3) 分析可获得全基因组microRNA图谱；4) 用于新microRNA鉴定、差异表达、聚类和表达谱分析。", "kp": "ch14_s0_12"}, {"id": "ch14_term_10", "modI": 0, "term": "ChIP-seq", "def": "染色质免疫共沉淀测序。要点：1) 通过抗体特异性富集与蛋白质结合的DNA片段；2) 再高通量测序；3) 用于定位转录因子结合位点或组蛋白修饰区域；4) 是表观组学测序的重要方法之一。", "kp": "ch14_s0_8"}, {"id": "ch14_term_11", "modI": 0, "term": "Bisulfite sequencing", "def": "重硫酸盐测序，DNA甲基化研究的经典方法。要点：1) 未甲基化胞嘧啶转化为尿嘧啶，甲基化胞嘧啶不变；2) 常见方法包括全基因组重硫酸盐测序（MethylC-seq/BS-seq）和简化表达重硫酸盐测序（RRBS）；3) 5hmC也会抵抗重硫酸盐转化；4) 可用hMeDIP-seq、oxBS-seq或TAB-seq等方法区分5hmC。", "kp": "ch14_s0_4"}, {"id": "ch14_term_12", "modI": 0, "term": "Single-cell sequencing (SCS)", "def": "单细胞测序技术。要点：1) 传统测序通常使用大量混合细胞，结果反映细胞群体平均信号，可能掩盖细胞异质性；2) SCS可在单细胞水平检测基因组和转录组；3) 可揭示干细胞多能性、肿瘤异质性、免疫治疗反应和罕见细胞类型；4) 流程一般包括单细胞分离、裂解、逆转录、扩增、文库构建和高通量测序；5) 在癌症、免疫治疗、循环肿瘤细胞（CTC）和早期胚胎细胞研究中意义重大；6) 2016年启动的人类细胞图谱计划是重要代表。", "kp": "ch14_s0_4"}], "preview": {"main": "本章围绕新一代测序技术展开，先回顾Sanger测序并介绍第二代和第三代测序平台及其原理，重点包括454、Illumina/Solexa和SOLiD；随后讲解第二代测序在RNA-seq、小RNA、lncRNA、ChIP-seq、DNA甲基化、单细胞测序和宏基因组学中的应用；最后讨论生物信息学分析流程、常用工具、新技术发展趋势及数据挑战。", "questions": ["第二代测序与第三代测序在原理、读长、通量和成本上有哪些主要区别？", "Roche 454、Illumina/Solexa和SOLiD三种平台的测序原理和流程分别是什么？", "RNA-seq在无参考基因组和有参考基因组时，生物信息学分析策略有何不同？", "ChIP-seq、BS-seq和RRBS分别用于研究哪些表观遗传问题？其基本流程是什么？", "单细胞测序、宏基因组学和Hi-C技术之间如何相互补充？它们面临哪些生物信息学挑战？"]}, "appcards": [{"front": "应用/分析型问题：某实验室希望从一份环境宏基因组样本中同时获得微生物群落组成和其中优势菌的完整基因组，并尽可能减少组装碎片化。请结合本章内容，设计一条合理的技术路线并说明理由。", "back": "要点式参考答案：1）先对宏基因组样本进行二代高通量短读长测序（如Illumina），用于群落组成分析、物种注释和丰度估计；2）对同一或类似样本进行三代单分子长读长测序，利用长读长跨越重复区域，提高宏基因组组装连续性；3）可结合Hi-C技术，通过染色质构象信息将来自同一微生物的contig聚类和分箱，辅助不同微生物基因组的组装；4）若目标微生物丰度低，可考虑单细胞测序或单细胞分选后测序，避免环境DNA背景干扰；5）最后结合生物信息学工具进行序列匹配、组装、注释和比较分析。", "points": "踩分点：二代短读长用于群落组成/丰度；三代长读长提高组装连续性；Hi-C辅助宏基因组分箱组装；单细胞测序辅助低丰度或难培养微生物；生物信息学组装与注释流程。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：在RNA-seq数据分析中，如果研究对象没有参考基因组，应如何开展转录组分析？若有参考基因组，又有哪些常见策略？请比较其分析思路。", "back": "要点式参考答案：无参考基因组时：1）先进行测序数据产量统计、去冗余、数据成分与质量评估；2）用Cufflinks等软件重建转录本；3）计算Contig/Scaffold和Unigene长度分布；4）进行功能注释、GO分类、代谢通路分析；5）获得Unigene表达量并进行差异表达、聚类等分析。有参考基因组时：1）可采用“先匹配再组装”，即将reads先比对到参考基因组，再合并分散片段为转录本；2）也可采用“先组装再匹配”，即先将reads组装成转录本，再比对到基因组；3）进一步分析可变剪接、新转录本、基因融合、SNP/InDel等。", "points": "踩分点：无参考基因组需de novo组装与注释；有参考基因组可先比对或先组装；Cufflinks等工具；质量评估、功能注释、GO/通路、差异表达；可变剪接、新转录本、基因融合等。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：某研究团队想同时分析肿瘤样本中的DNA甲基化状态、组蛋白修饰区域和基因表达变化。请基于第二代测序技术，提出可组合使用的测序策略，并说明各策略的主要用途。", "back": "要点式参考答案：1）DNA甲基化分析：可采用全基因组重硫酸盐测序（MethylC-seq/BS-seq）或简化表达重硫酸盐测序（RRBS），检测未甲基化C转化为U、甲基化C不变的位点；2）组蛋白修饰和转录因子结合分析：可采用ChIP-seq，通过抗体免疫沉淀结合DNA，经超声打断、接头连接、PCR扩增和高通量测序，统计Unique mapped reads在重复区域、基因区间、基因上的分布和覆盖深度；3）基因表达分析：可采用RNA-seq，分析转录本表达、差异表达、可变剪接、新转录本和基因融合等；4）整合分析：将甲基化、ChIP-seq和RNA-seq数据联合，研究表观遗传修饰对基因表达的调控。", "points": "踩分点：BS-seq/RRBS用于DNA甲基化；ChIP-seq用于组蛋白修饰/蛋白-DNA结合；RNA-seq用于表达分析；多组学整合；重硫酸盐处理原理；ChIP-seq流程关键步骤。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}, {"front": "应用/分析型问题：单细胞测序、宏基因组学和Hi-C技术之间有何联系？它们分别能解决哪些传统测序难以解决的问题？", "back": "要点式参考答案：1）单细胞测序可研究细胞异质性，如癌症内异质性、肿瘤循环细胞（CTC）、早期胚胎细胞等数量不足的细胞，并提升基因表达测量精度和罕见非编码RNA发现能力；2）宏基因组学可研究人体共生微生物群落结构、分子过程与健康关系，如人类微生物组计划（HMP）分析鼻腔、口腔、皮肤、胃肠道和泌尿生殖道样本；3）Hi-C技术通过染色质交联、酶切、生物素标记、连接、纯化和测序，研究三维基因组结构，并可辅助宏基因组中不同微生物基因组的组装；4）第三代单分子测序可免去单细胞测序中的扩增步骤，提高精确性；单细胞测序可辅助宏基因组测序发现新细菌；Hi-C可帮助宏基因组组装。", "points": "踩分点：单细胞测序解决细胞异质性和微量细胞问题；宏基因组研究微生物群落与健康；Hi-C研究三维基因组并辅助宏基因组组装；三代测序与单细胞测序互补；新技术间相互促进。", "mod": 0, "modName": "第十四章 新一代测序技术及其应用", "level": "掌握", "src": "生成"}]};